function preservationLabel(value) { return (state.language === 'en' ? preservationNamesEn : preservationNames)[value || 'not_evaluated']; }
function dentalLabel(value) { return (state.language === 'en' ? dentalNamesEn : dentalNames)[value || 'not_observable']; }
function dentalSet() { return state.dentitionType==='deciduous'?deciduousTeeth:teeth; }
function dentalState() { return state.dentitionType==='deciduous'?state.deciduousDental:state.dental; }
function renderDental() { const set=dentalSet(); const values=dentalState(); const grid=document.querySelector('#dental-grid'); grid.innerHTML=set.map(tooth=>`<button class="tooth tooth-${values[tooth]||'not_recorded'}" data-tooth="${tooth}" title="${dentalLabel(values[tooth])}">${tooth}<small>${dentalLabel(values[tooth])}</small></button>`).join(''); document.querySelector('#dentition-type').value=state.dentitionType; grid.querySelectorAll('[data-tooth]').forEach(button=>button.onclick=()=>{const tooth=button.dataset.tooth;const previous=values[tooth]||'not_recorded';values[tooth]=state.dentalStatus;recordInventoryFieldChange(tooth,state.dentitionType==='deciduous'?'deciduousDentalStatus':'dentalStatus',previous,values[tooth],'dental');renderDental();updateDentalCount();saveLocal();document.querySelector('#toast').textContent=`Diente ${tooth} → ${dentalLabel(state.dentalStatus)}`;}); }
function updateDentalCount() { const set=dentalSet(); const values=dentalState(); const count=set.filter(t=>values[t]&&values[t]!=='not_observable').length; document.querySelector('#dental-count').textContent=`${count}/${set.length}`; }
function renderMetrics() { const m=state.measurements[state.selected]||{}; document.querySelector('#metric-length').value=m.length??''; document.querySelector('#metric-width').value=m.width??''; document.querySelector('#metric-height').value=m.height??''; const list=state.landmarks[state.selected]||[]; document.querySelector('#landmark-list').innerHTML=list.map((p,i)=>`<div class="landmark-row"><span>${p.name}</span><small>(${p.x}, ${p.y}, ${p.z})</small><button data-remove-landmark="${i}">×</button></div>`).join(''); document.querySelectorAll('[data-remove-landmark]').forEach(b=>b.onclick=()=>{const previous=structuredClone(list);list.splice(+b.dataset.removeLandmark,1);recordInventoryFieldChange(state.selected,'landmarks',previous,list,'landmark_remove');renderMetrics();saveLocal();}); const measured=Object.values(state.measurements).filter(x=>x.length||x.width||x.height).length; document.querySelector('#stats-box').textContent=`Elementos con medición: ${measured}/${bones.length}`; }
function saveMetrics() { const previous=structuredClone(state.measurements[state.selected]||null); state.measurements[state.selected]={length:+document.querySelector('#metric-length').value||null,width:+document.querySelector('#metric-width').value||null,height:+document.querySelector('#metric-height').value||null,unit:'mm'}; recordInventoryFieldChange(state.selected,'measurements',previous,state.measurements[state.selected],'measurements'); renderMetrics(); saveLocal(); document.querySelector('#toast').textContent='Mediciones guardadas'; }
function addLandmark() { const name=document.querySelector('#landmark-name').value.trim(); if(!name)return; const previous=structuredClone(state.landmarks[state.selected]||[]); if(!state.landmarks[state.selected])state.landmarks[state.selected]=[]; state.landmarks[state.selected].push({name,x:+document.querySelector('#landmark-x').value||0,y:+document.querySelector('#landmark-y').value||0,z:+document.querySelector('#landmark-z').value||0}); recordInventoryFieldChange(state.selected,'landmarks',previous,state.landmarks[state.selected],'landmark'); ['landmark-name','landmark-x','landmark-y','landmark-z'].forEach(id=>document.querySelector('#'+id).value=''); renderMetrics(); saveLocal(); }
function renderStats() { const visible=bones.filter(matchesFilters); const reviewed=visible.filter(b=>(state.status[b.id]||'not_recorded')!=='not_recorded').length; const present=visible.filter(b=>state.status[b.id]==='present').length; const fragmentary=visible.filter(b=>state.status[b.id]==='fragmentary').length; const preserved=visible.filter(b=>state.completeness[b.id]!=null).reduce((sum,b)=>sum+(state.completeness[b.id]??0),0); const average=reviewed?Math.round(preserved/reviewed):0; document.querySelector('#stats-summary').innerHTML=`<div><strong>${reviewed}/${visible.length}</strong><small>revisados tras filtros</small></div><div><strong>${present}</strong><small>presentes</small></div><div><strong>${fragmentary}</strong><small>fragmentarios</small></div><div><strong>${average}%</strong><small>conservación media registrada</small></div>`; }
function reportHtml() { const reviewed=bones.filter(b=>(state.status[b.id]||'not_recorded')!=='not_recorded').length; const present=bones.filter(b=>state.status[b.id]==='present').length; const fragmentary=bones.filter(b=>state.status[b.id]==='fragmentary').length; const dentalCount=teeth.filter(t=>state.dental[t]&&state.dental[t]!=='not_observable').length; const rows=bones.map(b=>`<tr><td>${escapeHtml(b.es)}</td><td>${escapeHtml(b.side)}</td><td>${escapeHtml(statusLabel(state.status[b.id]))}</td><td>${escapeHtml(preservationLabel(state.preservation[b.id]))}</td><td>${state.completeness[b.id]??'—'}%</td></tr>`).join(''); const report=state.report||{}; const individual=report.individual||'—'; const site=report.site||'—'; const context=report.context||'—'; const investigator=report.investigator||'—'; return `<!doctype html><html lang="es"><head><meta charset="utf-8"><title>Informe osteoarqueológico · ${escapeHtml(individual)}</title><style>body{font:14px system-ui;color:#243b53;max-width:1000px;margin:32px auto}h1{color:#102a43}h2{border-bottom:1px solid #bcccdc;padding-bottom:6px;margin-top:28px}dl{display:grid;grid-template-columns:180px 1fr}dt,dd{padding:6px;margin:0;border-bottom:1px solid #e4e7eb}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:6px;border-bottom:1px solid #e4e7eb}.report-photos{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.report-photos img{max-width:100%;max-height:240px;object-fit:contain}@media print{body{margin:12mm}button{display:none}}</style></head><body><h1>Informe osteoarqueológico</h1><dl><dt>Individuo</dt><dd>${escapeHtml(individual)}</dd><dt>Yacimiento</dt><dd>${escapeHtml(site)}</dd><dt>Contexto</dt><dd>${escapeHtml(context)}</dd><dt>Investigador</dt><dd>${escapeHtml(investigator)}</dd><dt>Fecha de generación</dt><dd>${new Date().toLocaleString('es-ES')}</dd></dl><h2>Resumen</h2><p>Elementos revisados: <strong>${reviewed}/${bones.length}</strong>. Presentes: <strong>${present}</strong>. Fragmentarios: <strong>${fragmentary}</strong>. Piezas dentales registradas: <strong>${dentalCount}/${teeth.length}</strong>.</p><h2>Inventario esquelético</h2><table><thead><tr><th>Elemento</th><th>Lado</th><th>Estado</th><th>Conservación</th><th>Porcentaje</th></tr></thead><tbody>${rows}</tbody></table><h2>Mediciones y landmarks</h2><p>Elementos con osteometría: ${Object.keys(state.measurements).length}. Elementos con landmarks: ${Object.keys(state.landmarks).length}.</p></body></html>`; }
function dentalReportHtml() { const table=(title,set,values)=>`<h2>${title}</h2><table><thead><tr><th>FDI</th><th>Estado</th></tr></thead><tbody>${set.map(tooth=>`<tr><td>${escapeHtml(tooth)}</td><td>${escapeHtml(dentalLabel(values[tooth]))}</td></tr>`).join('')}</tbody></table>`; return table('Odontograma permanente',teeth,state.dental)+table('Odontograma deciduo',deciduousTeeth,state.deciduousDental); }
function analysisReportHtml() { const analysis=calculateOsteoAnalysis(bones,state); const measurementRows=Object.entries(state.measurements||{}).filter(([,value])=>value&&Object.values(value).some(item=>item!=null&&item!=='')); const landmarkRows=Object.entries(state.landmarks||{}).flatMap(([boneId,points])=>(Array.isArray(points)?points:[]).map(point=>({boneId,point}))); return `<h2>Análisis cuantitativo</h2><p>NISP: <strong>${analysis.nisp.value}</strong> · MNE: <strong>${analysis.mne.value}</strong> · MNI: <strong>${analysis.mni.value}</strong> · Individuos: <strong>${analysis.individuals.value}</strong></p><dl><dt>Método NISP</dt><dd>${escapeHtml(analysis.nisp.method)}</dd><dt>Método MNE</dt><dd>${escapeHtml(analysis.mne.method)}</dd><dt>Método MNI</dt><dd>${escapeHtml(analysis.mni.method)}</dd></dl><h2>Detalle osteométrico</h2><table><thead><tr><th>Elemento</th><th>Longitud</th><th>Anchura</th><th>Altura</th><th>Diámetro</th><th>Unidad</th></tr></thead><tbody>${measurementRows.map(([boneId,value])=>`<tr><td>${escapeHtml(bones.find(bone=>bone.id===boneId)?.es||boneId)}</td><td>${escapeHtml(value.length)}</td><td>${escapeHtml(value.width)}</td><td>${escapeHtml(value.height)}</td><td>${escapeHtml(value.diameter)}</td><td>${escapeHtml(value.unit||'mm')}</td></tr>`).join('')||'<tr><td colspan="6">Sin mediciones registradas</td></tr>'}</tbody></table><p>Landmarks registrados: <strong>${landmarkRows.length}</strong>.</p>`; }
function photosReportHtml() { const photos=Object.entries(state.photos||{}).flatMap(([scope,items])=>(Array.isArray(items)?items:[]).map(photo=>({scope,photo}))).filter(({photo})=>/^data:image\/(?:png|jpe?g|gif|webp);base64,/i.test(String(photo.dataUrl||''))); if(!photos.length)return '<h2>Fotografías</h2><p>Sin fotografías locales seleccionadas.</p>'; return `<h2>Fotografías locales</h2><div class="report-photos">${photos.map(({scope,photo})=>`<figure><img src="${escapeHtml(photo.dataUrl)}" alt="${escapeHtml(photo.name||'Fotografía')}"/><figcaption>${escapeHtml(photo.name||'Fotografía')} · ${escapeHtml(scope)}</figcaption></figure>`).join('')}</div>`; }
function reportContextHtml() { const report=state.report||{}; const fields=reportContextFields.filter(([key])=>report[key]).map(([key,label])=>`<dt>${label}</dt><dd>${escapeHtml(report[key])}</dd>`).join(''); return fields?`<h2>Ficha de contexto</h2><dl>${fields}</dl>`:''; }
const reportHtmlBase = reportHtml;
reportHtml = (...args) => reportHtmlBase(...args).replace('</body>', `${reportContextHtml()}${dentalReportHtml()}${analysisReportHtml()}${photosReportHtml()}</body>`);
function previewReport() { document.querySelector('#report-preview').innerHTML=`<strong>${state.report.individual||'IND-LOCAL'}</strong> · ${bones.filter(b=>(state.status[b.id]||'not_recorded')!=='not_recorded').length}/${bones.length} elementos revisados`; }
const reportContextFields = [['burial','Enterramiento'],['grave','Sepultura'],['tomb','Tumba'],['ue','UE'],['sector','Sector'],['grid','Cuadrícula'],['campaign','Campaña'],['date','Fecha'],['chronology','Cronología'],['observations','Observaciones']];
function ensureReportContextFields() { const fields=document.querySelector('.report-fields'); if(!fields||document.querySelector('#report-burial'))return; const markup=reportContextFields.map(([key,label])=>`<label>${label}${key==='observations'?`<textarea id="report-${key}" rows="2"></textarea>`:`<input id="report-${key}"${key==='date'?' type="date"':''}/>`}</label>`).join(''); document.querySelector('#report-individual')?.insertAdjacentHTML('afterend',markup); }
setTimeout(ensureReportContextFields,0);
function saveReportData() { ensureReportContextFields(); const report={}; ['individual','site','context','investigator',...reportContextFields.map(([key])=>key)].forEach(key=>{const element=document.querySelector('#report-'+key);if(element)report[key]=element.value.trim();}); state.report={...state.report,...report}; saveLocal(); previewReport(); }
function populateReportFields() { ensureReportContextFields(); const report=state.report||{}; ['individual','site','context','investigator',...reportContextFields.map(([key])=>key)].forEach(key=>{const element=document.querySelector('#report-'+key);if(element)element.value=report[key]||'';}); }
setTimeout(() => document.querySelector('#tab-report')?.addEventListener('click', populateReportFields), 0);
function printReport() { saveReportData(); const win=window.open('','_blank'); if(!win)return; const totalWeight=bones.reduce((sum,b)=>sum+(Number.isFinite(Number(state.weights[b.id]))?Number(state.weights[b.id]):0),0); const indeterminateWeight=(state.indeterminateFragments||[]).reduce((sum,item)=>sum+(Number.isFinite(Number(item.weight))&&Number(item.weight)>=0?Number(item.weight):0),0); const indeterminateCount=(state.indeterminateFragments||[]).length; const html=reportHtml().replace('</body>',`<p><strong>Peso total registrado (identificado):</strong> ${totalWeight.toFixed(2)} g</p><p><strong>Fragmentos indeterminados:</strong> ${indeterminateCount} · ${indeterminateWeight.toFixed(2)} g (excluidos de NISP/MNE/MNI)</p></body>`); win.document.write(html); win.document.close(); win.focus(); setTimeout(()=>win.print(),250); }
function photoKey() { const scope=document.querySelector('#photo-scope')?.value||state.photoScope||'bone'; if(scope==='bone')return state.selected; const target=document.querySelector('#photo-target')?.value.trim()||state.photoTargetId||state.report?.individual||'IND-LOCAL'; return `${scope}:${target}`; }
function renderPhotos() { const list=document.querySelector('#photo-list'); if(!list)return; const photos=state.photos[photoKey()]||[]; list.innerHTML=photos.map((photo,index)=>`<figure><img src="${photo.dataUrl}" alt="${escapeHtml(photo.name)}"><figcaption>${escapeHtml(photo.name)}<button data-remove-photo="${index}">×</button></figcaption></figure>`).join(''); list.querySelectorAll('[data-remove-photo]').forEach(button=>button.onclick=()=>{photos.splice(+button.dataset.removePhoto,1);renderPhotos();saveLocal();}); }
function addPhotos(files) { const key=photoKey(); if(!state.photos[key])state.photos[key]=[]; [...files].filter(file=>file.type.startsWith('image/')).forEach(file=>{if(file.size>12*1024*1024){document.querySelector('#toast').textContent=`Foto rechazada por tamaño: ${file.name}`;return;} const reader=new FileReader();reader.onload=()=>{const image=new Image();image.onload=()=>{const max=1800;const scale=Math.min(1,max/Math.max(image.naturalWidth,image.naturalHeight));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(image.naturalWidth*scale));canvas.height=Math.max(1,Math.round(image.naturalHeight*scale));canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);const type=file.type==='image/png'?'image/png':'image/jpeg';const dataUrl=canvas.toDataURL(type,type==='image/jpeg'?0.82:undefined);state.photos[key].push({name:file.name,type,dataUrl,width:canvas.width,height:canvas.height});renderPhotos();saveLocal();};image.onerror=()=>{document.querySelector('#toast').textContent=`Foto no válida: ${file.name}`;};image.src=reader.result;};reader.readAsDataURL(file);}); }
async function protectLocalStorage() { const status=document.querySelector('#storage-status'); if(!status||!navigator.storage?.persist) return; try { let persisted=await navigator.storage.persisted(); if(!persisted) persisted=await navigator.storage.persist(); status.textContent=persisted?'Datos locales protegidos':'Datos locales'; status.classList.toggle('protected',persisted); } catch { status.textContent='Datos locales'; } }
async function runPwaDiagnostics() { const list=document.querySelector('#pwa-diagnostics-status'); if(!list)return; const checks=[]; const add=(label,ok,detail)=>checks.push(`<li class="${ok?'ok':'pending'}"><span aria-hidden="true">${ok?'✓':'○'}</span> ${label}: ${detail}</li>`); const hasServiceWorker='serviceWorker' in navigator; if(!hasServiceWorker){add('Service Worker',false,'no disponible');} else { const registration=await navigator.serviceWorker.getRegistration(); add('Service Worker',!!registration,registration?'registrado':'pendiente'); } let shellCached=false; try { const cache=globalThis.caches && await caches.open('osteo3d-shell-v7'); const shellEntries=['./index.html','./manifest.json','./models/manifest.json','./models/sources.json','./icons/osteo3d-192.png','./icons/osteo3d-512.png']; const results=await Promise.all(shellEntries.map(path=>cache?.match(path))); shellCached=results.every(Boolean); } catch {} add('Shell offline',shellCached,shellCached?'HTML, datos e iconos en caché':'pendiente de primera carga'); let manifestIcons=false; try { const manifestResponse=await fetch('./manifest.json',{cache:'no-store'}); const manifest=manifestResponse.ok?await manifestResponse.json():null; const icons=Array.isArray(manifest?.icons)?manifest.icons:[]; const results=await Promise.all(icons.map(icon=>fetch(icon.src,{cache:'no-store'}).then(response=>response.ok).catch(()=>false))); manifestIcons=manifestResponse.ok && icons.some(icon=>icon.type==='image/png') && icons.length>=2 && results.every(Boolean); } catch {} add('Iconos PWA',manifestIcons,'manifiesto e iconos '+(manifestIcons?'disponibles':'pendientes')); let persisted=false; try { persisted=!!navigator.storage?.persisted && await navigator.storage.persisted(); } catch {} add('Datos locales',persisted?'protegidos':'disponibles',persisted?'persistencia activa':'persistencia no confirmada'); const standalone=globalThis.matchMedia?.('(display-mode: standalone)').matches || globalThis.navigator?.standalone; const ios=/iphone|ipad|ipod/i.test(navigator.userAgent) || (navigator.platform==='MacIntel' && navigator.maxTouchPoints>1); const install=document.querySelector('#install-app'); const installReady=!!deferredInstallPrompt && !standalone; if(standalone){ add('Instalación',true,'modo instalado'); } else if(installReady){ add('Instalación',true,'disponible en este navegador'); if(install) install.hidden=false; } else if(ios){ add('Instalación',false,'Safari: Compartir → Añadir a pantalla de inicio'); } else { add('Instalación',false,'navegador (aún no ofrecida)'); } list.innerHTML=checks.join(''); }
async function registerPwa() { if(!('serviceWorker' in navigator)) return; const registration=await navigator.serviceWorker.register('./sw.js'); protectLocalStorage().catch(()=>{}); const updateActions=document.querySelector('#update-actions'); const updateButton=document.querySelector('#update-app'); const dismissButton=document.querySelector('#dismiss-update'); let updateRequested=false; const hideUpdate=()=>{if(updateActions)updateActions.hidden=true;}; const showUpdate=()=>{if(updateActions)updateActions.hidden=false;}; if(updateButton) updateButton.onclick=async()=>{ await saveLocal({ notify:false }); updateRequested=true; registration.waiting?.postMessage({type:'SKIP_WAITING'}); }; if(dismissButton) dismissButton.onclick=hideUpdate; if(registration.waiting) showUpdate(); registration.addEventListener('updatefound',()=>{const worker=registration.installing; worker?.addEventListener('statechange',()=>{if(worker.state==='installed' && navigator.serviceWorker.controller) showUpdate();});}); navigator.serviceWorker.addEventListener('controllerchange',()=>{if(updateRequested) window.location.reload();}); window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();deferredInstallPrompt=event;const install=document.querySelector('#install-app');if(install){install.hidden=false;install.onclick=async()=>{install.hidden=true;await deferredInstallPrompt.prompt();deferredInstallPrompt=null;runPwaDiagnostics();};} runPwaDiagnostics();}); window.addEventListener('appinstalled',()=>{deferredInstallPrompt=null;const install=document.querySelector('#install-app');if(install)install.hidden=true;runPwaDiagnostics();}); }
let modelPackagePanelRequest = 0;
function updateModelPackagePanel() { const statusElement=document.querySelector('#model-package-status'); const sizeElement=document.querySelector('#model-package-size'); const cacheElement=document.querySelector('#model-package-cache'); const action=document.querySelector('#model-package-action'); const remove=document.querySelector('#model-package-remove'); if(!statusElement||!action||!remove)return; const request=++modelPackagePanelRequest; if(!modelManifest){statusElement.textContent='Manifiesto GLB no disponible; se mantienen marcadores geométricos de desarrollo.';sizeElement.textContent='Tamaño aproximado: no disponible';cacheElement.textContent='Caché offline: no disponible';action.textContent='No disponible';action.disabled=true;remove.disabled=true;return;} const summary=modelPackageSummary(modelManifest,state.profile,bones); const labels={placeholder:'Pendiente de incorporar assets licenciados',partial:'Disponible parcialmente',ready:'Disponible para descarga',missing:'Perfil no definido'}; statusElement.textContent=`${summary.expected} elementos · ${labels[summary.status]||summary.status}.`; sizeElement.textContent=`Tamaño aproximado: ${formatPackageSize(summary.approximateSizeMb)}`; cacheElement.textContent='Caché offline: comprobando…'; action.disabled=!['ready','partial'].includes(summary.status); action.textContent=action.disabled?'No disponible':'Descargar paquete offline'; action.title=action.disabled?'Este perfil aún no tiene modelos GLB licenciados publicados.':'Guardar los modelos GLB del perfil en la caché offline.'; remove.disabled=true; getModelPackageCacheStatus(modelManifest,state.profile,bones).then(result=>{if(request!==modelPackagePanelRequest)return; cacheElement.textContent=`Caché offline: ${result.cached}/${result.expected} recursos`; remove.disabled=result.cached===0;}).catch(()=>{if(request===modelPackagePanelRequest)cacheElement.textContent='Caché offline: no disponible';}); }
async function downloadSelectedModelPackage() { const action=document.querySelector('#model-package-action'); const toast=document.querySelector('#toast'); if(!modelManifest||action?.disabled)return; const original=action.textContent; action.disabled=true; action.textContent='Descargando…'; try { const result=await downloadModelPackage(modelManifest,state.profile,bones); toast.textContent=`Paquete ${state.profile} guardado offline · ${result.downloaded} modelos`; } catch(error) { toast.textContent=error.message||'No se pudo descargar el paquete 3D.'; } finally { updateModelPackagePanel(); if(action && !action.disabled && action.textContent===original) action.textContent=original; } }
async function removeSelectedModelPackage() { const remove=document.querySelector('#model-package-remove'); const toast=document.querySelector('#toast'); if(!modelManifest||remove?.disabled)return; if(!window.confirm(`Se eliminarán los modelos GLB offline del perfil ${state.profile}. ¿Continuar?`))return; remove.disabled=true; try { const result=await removeModelPackage(modelManifest,state.profile,bones); toast.textContent=`Paquete ${state.profile} eliminado · ${result.removed} recursos`; } catch(error) { toast.textContent=error.message||'No se pudo eliminar el paquete 3D.'; } finally { updateModelPackagePanel(); } }
async function importLocalModelFiles(files) { const toast=document.querySelector('#toast'); if(!files.length)return; if(!window.confirm(`La importación reemplazará los modelos GLB locales coincidentes del perfil ${state.profile}. ¿Continuar?`))return; try { const result=await importModelPackageFiles(state.profile,files,bones.map(bone=>bone.id)); await loadAvailableProfileModels(); updateModelPackagePanel(); toast.textContent=`GLB locales importados · ${result.importedCount}${result.rejectedCount ? ` · rechazados ${result.rejectedCount}` : ''}`; } catch(error) { toast.textContent=error.message||'No se pudieron importar los modelos GLB.'; } }
async function importCustomModel(file) { const toast=document.querySelector('#toast'); const bone=bones.find(item=>item.id===state.selected); if(!file||!bone||!THREE||!group)return; if(!window.confirm(`El modelo local se asociará a ${bone.es} en la sesión actual. ¿Continuar?`))return; try { const loaded=await loadLocalModel(THREE,file); const root=loaded.scene || loaded; root.name=bone.id; root.position.set(...bone.p); root.userData={...bone,boneId:bone.id,modelSource:'custom',baseScale:root.scale.clone()}; root.traverse(node=>{node.userData={...node.userData,boneId:bone.id};}); const previous=group.getObjectByName(bone.id); if(previous){group.remove(previous);disposeObject(previous);} group.add(root); loadedModelObjects.set(bone.id,root); state.customModels ||= {}; state.customModels[state.profile] ||= {}; state.customModels[state.profile][bone.id]={fileName:file.name,format:String(file.name).split('.').pop().toLowerCase(),updatedAt:new Date().toISOString()}; await saveLocal({notify:false}); selectBone(bone.id); toast.textContent=`Modelo propio cargado · ${bone.es}`; } catch(error) { toast.textContent=error.message||'No se pudo cargar el modelo propio.'; } }
async function verifyModelPackages() { try { modelManifest=await loadModelManifest(); modelSourceRegistry=await loadModelSourceRegistry(modelManifest); const statuses=Object.values(modelManifest.profiles).map(profile=>profile.asset_status); const ready=statuses.filter(status=>status==='ready').length; const registered=Object.values(modelSourceRegistry.profiles || {}).filter(source=>source.source_status!=='pending').length; document.querySelector('.side-note').textContent=`Manifiesto GLB válido · ${ready}/${statuses.length} perfiles con assets documentados · registro de fuentes válido (${registered} con fuente publicada). Las geometrías actuales son marcadores de desarrollo.`; } catch { modelSourceRegistry=null; if (!modelManifest) document.querySelector('.side-note').textContent='Manifiesto GLB o registro de fuentes no disponible; se mantienen marcadores geométricos de desarrollo.'; else document.querySelector('.side-note').textContent='Manifiesto GLB válido, pero el registro de fuentes necesita revisión; se mantienen marcadores geométricos de desarrollo.'; } updateModelPackagePanel(); }
