 function exportInventory(format) { const report=state.report||{}; const rows=bones.map(b=>({Individual_ID:state.individuals[b.id]||report.individual||'IND-LOCAL',Burial:report.burial||'',Grave:report.grave||'',Tomb:report.tomb||'',Site:report.site||'',Campaign:report.campaign||'',Date:report.date||'',Sector:report.sector||'',Grid:report.grid||'',Context:report.context||'',Chronology:report.chronology||'',UE:state.ue?.[b.id]||report.ue||'',Bone_ID:b.id,Bone_Name:b.es,Side:b.side,Presence:state.status[b.id]||'not_recorded',Preservation:state.preservation[b.id]||'not_evaluated',Completeness:state.completeness[b.id]??100,Percentage:state.completeness[b.id]??100,Fragments:state.fragments[b.id]||0,Weight_g:state.weights[b.id]??'',Portion:state.portions[b.id]||'whole',Taphonomy:(state.taphonomy[b.id]||[]).join(', '),Pathology:(state.pathology[b.id]||[]).join(', '),Notes:state.notes[b.id]||report.observations||'',Locked:!!state.locked[b.id],Region:b.region})); if(format==='json') downloadFile('osteo3d-inventory.json',JSON.stringify({profile:state.profile,report,records:rows,indeterminateFragments:state.indeterminateFragments||[],dentition:state.dental,deciduousDentition:state.deciduousDental,measurements:state.measurements,landmarks:state.landmarks,changeLog:state.changeLog},null,2),'application/json'); else { const fields=Object.keys(rows[0]); const csv=[fields.join(','),...rows.map(row=>fields.map(f=>`"${String(row[f]).replaceAll('"','""')}"`).join(','))].join('\n'); downloadFile('osteo3d-inventory.csv',csv,'text/csv;charset=utf-8'); } }
