function applyProjectData(saved) {
  if (!saved) return;
  Object.assign(state, saved, { projectId: saved.id || saved.projectId || 'default', projectName: saved.projectName || saved.name || 'Proyecto sin título', history: [], future: [], inventoryMode: false, pendingOnly: false, activeStatus: 'present' });
  state.hidden = saved.hidden || {};
  state.opacity = saved.opacity || {};
  state.opacityScope = ['bone', 'region', 'skeleton'].includes(saved.opacityScope) ? saved.opacityScope : 'bone';
  state.wireframe = Boolean(saved.wireframe);
  state.xray = Boolean(saved.xray);
  state.labelMode = ['selected', 'region', 'all', 'none'].includes(saved.labelMode) ? saved.labelMode : 'selected';
  state.colorByRegion = saved.colorByRegion !== false;
  state.comparisonProfile = saved.comparisonProfile || '';
  state.tableTransforms = saved.tableTransforms || {};
  state.lightIntensity = Number.isFinite(saved.lightIntensity) ? saved.lightIntensity : 1;
  setLightIntensity(state.lightIntensity);
  document.querySelector('#opacity-scope') && (document.querySelector('#opacity-scope').value = state.opacityScope);
  document.querySelector('#label-mode') && (document.querySelector('#label-mode').value = state.labelMode);
  const xrayButton = document.querySelector('#xray-toggle');
  if (xrayButton) { xrayButton.setAttribute('aria-pressed', String(state.xray)); xrayButton.textContent = state.xray ? 'X-Ray activado' : 'X-Ray'; }
  const regionColorsButton = document.querySelector('#region-colors-toggle');
  if (regionColorsButton) { regionColorsButton.setAttribute('aria-pressed', String(state.colorByRegion)); regionColorsButton.textContent = state.colorByRegion ? 'Colores por región' : 'Color neutro'; }
  setComparisonProfile(state.comparisonProfile);
  document.querySelector('#profile').value = state.profile;
  document.querySelector('#language').value = state.language;
  document.documentElement.lang = state.language;
  extendedUi?.updateLabels();
  document.querySelector('#dentition-type').value = state.dentitionType;
  ['status', 'region', 'side', 'taphonomy', 'pathology'].forEach(key => { const element = document.querySelector('#filter-' + key); if (element) element.value = state.filters[key]; });
  renderDental(); updateDentalCount(); renderList(); selectBone(state.selected || 'skull'); updateInventory(); renderStats();
  const selector = document.querySelector('#project-selector'); if (selector) selector.value = state.projectId;
  document.querySelector('#toast').textContent = `Proyecto cargado · ${state.projectName}`;
}
async function refreshProjectSelector() {
  const selector = document.querySelector('#project-selector'); if (!selector) return;
  let projects = await listProjects();
  if (!projects.some(project => project.id === state.projectId)) { await saveLocal({ notify: false }); projects = await listProjects(); }
  const escapeMarkup = value => String(value ?? '').replace(/[&<>"']/g, character => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[character]));
  selector.innerHTML = projects.map(project => `<option value="${escapeMarkup(project.id)}">${escapeMarkup(project.projectName || project.id)}</option>`).join('');
  selector.value = state.projectId;
}
async function initProjectManager() {
  await refreshProjectSelector();
  const selector = document.querySelector('#project-selector');
  selector.onchange = async () => { await saveLocal({ notify: false }); applyProjectData(await loadProject(selector.value)); await refreshProjectSelector(); };
  document.querySelector('#new-project').onclick = async () => {
    const name = window.prompt('Nombre del nuevo proyecto', 'Proyecto osteológico');
    if (!name?.trim()) return;
    await saveLocal({ notify: false });
    Object.assign(state, { projectId: `project-${Date.now()}`, projectName: name.trim(), profile: 'adult_male', selected: 'skull', status: {}, preservation: {}, completeness: {}, fragments: {}, portions: {}, individuals: {}, taphonomy: {}, pathology: {}, notes: {}, locked: {}, changeLog: [], quickPresent: false, dental: {}, deciduousDental: {}, dentitionType: 'permanent', measurements: {}, landmarks: {}, photos: {}, language: 'es', filters: { status: 'all', region: 'all', side: 'all', taphonomy: 'all', pathology: 'all' }, report: { individual: 'IND-LOCAL', site: '', context: '', investigator: '' } });
    await saveLocal({ notify: false }); applyProjectData(state); await refreshProjectSelector();
  };
}
